// Data structure for province circles
struct ProvinceCircle {
    int x, y; // Pixel location on the image
};

// Data structure for a polygon
struct ProvincePolygon {
    std::vector<Vector2> points; // Pixel positions on image
    Color fillColor;             // Polygon fill color
    bool outline;                // Is outline on?
};

// Function to draw a pixel-fitting circle at given image coords (x, y)
void drawProvince(const ProvinceCircle& circle, const Texture2D& image, const Camera2D& camera) {
    // Each pixel = 1 in image coords, so draw a circle that fits perfectly in (x, y)
    Vector2 imgPos = { (float)circle.x + 0.5f, (float)circle.y + 0.5f };
    // Transform image coordinates to screen
    Vector2 screenPos = GetWorldToScreen2D(imgPos, camera);

    // Calculate size of one image pixel on screen at current zoom
    float zoom = camera.zoom;
    float pixelWidth = zoom; // since 1 px on image == 1 unit world
    float pixelHeight = zoom;

    // The circle should fit snug in the pixel: so radius = 0.5*min(pixelWidth, pixelHeight)
    float radius = 0.5f * ((pixelWidth < pixelHeight) ? pixelWidth : pixelHeight);

    DrawCircleV(screenPos, radius, RED);
}

void drawPolygon(const ProvincePolygon& polygon, const Camera2D& camera)
{
    size_t n = polygon.points.size();
    if (n < 2) return;

    // Transform all polygon points to screen
    std::vector<Vector2> screenPts;
    for (size_t i=0; i<n; ++i) {
        screenPts.push_back(GetWorldToScreen2D(polygon.points[i], camera));
    }

    // Prepare color with desired random fill
    Color fill = polygon.fillColor;
    // To draw filled polygon, we need at least 3 points
    if (n >= 3) {
        // Prepare array of pts
        std::vector<Vector2> verts = screenPts;
        DrawPoly((Vector2){0, 0}, 3, 0, 0, BLANK); // dummy to pull in function
        DrawTriangleFan(&verts[0], (int)verts.size(), fill);
    }
    // Draw outline if enabled
    if (polygon.outline) {
        for (size_t i=0; i<n; ++i) {
            Vector2 p1 = screenPts[i];
            Vector2 p2 = screenPts[(i+1)%n];
            DrawLineEx(p1, p2, 2.0f, RED);
        }
    }
    // Draw circles at the vertices
    for (size_t i=0; i<n; ++i) {
        DrawCircleV(screenPts[i], 5.0f, RED);
    }
}

