def manage_parole_officer_schedules(officers):
    schedule = {
        "Monday": [],
        "Tuesday": [],
        "Wednesday": [],
        "Thursday": [],
        "Friday": [],
        "Saturday": [],
        "Sunday": []
    }

    for officer in officers:
        name = officer["name"]
        available_days = officer["available_days"]
        for day in available_days:
            schedule[day].append(name)

    return schedule

