def is_valid_sequence(sequence):
    is_even = True
    for num in sequence:
        if (num % 2 == 0) != is_even:
            return False
        is_even = not is_even
    return True

class CustomDict:
    def __init__(self):
        self.keys = []
        self.values = []

    def __setitem__(self, key, value):
        if key in self.keys:
            self.values[self.keys.index(key)] = value
        else:
            self.keys.append(key)
            self.values.append(value)

    def __getitem__(self, key):
        if key not in self.keys:
            raise KeyError(key)
        return self.values[self.keys.index(key)]

    def __contains__(self, key):
        return key in self.keys

def fibonacci(n, memo=None):
    if memo is None:
        memo = CustomDict()
    if n in memo:
        return memo[n]
    if n <= 2:
        return 1
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    return memo[n]

def main():
    n = int(input())
    print(fibonacci(n))

if __name__ == "__main__":
    main()

def main():
    import sys
    input_line = sys.stdin.read().strip()
    if not input_line:
        print("")
        return
    nums = list(map(int, input_line.split()))
    if not nums:
        print("")
        return
    num_set = set(nums)
    longest_streak = []

    for num in num_set:
        if num - 1 not in num_set:
            current_num = num
            current_streak = [current_num]
            while current_num + 1 in num_set:
                current_num += 1
                current_streak.append(current_num)
            if len(current_streak) > len(longest_streak):
                longest_streak = current_streak
            elif len(current_streak) == len(longest_streak):
                # Use the one whose smallest member is earlier in sorted order
                if current_streak[0] < longest_streak[0]:
                    longest_streak = current_streak
    print(' '.join(str(x) for x in longest_streak))

if __name__ == "__main__":
    main()

def calculate_average_cell_density(samples):
    tissue_densities = {}

    for sample in samples:
        tissue_type = sample['tissue_type']
        cell_count = sample['cell_count']
        volume = sample['volume']

        if tissue_type in tissue_densities:
            tissue_densities[tissue_type]['total_cell_count'] += cell_count
            tissue_densities[tissue_type]['total_volume'] += volume
        else:
            tissue_densities[tissue_type] = {
                'total_cell_count': cell_count,
                'total_volume': volume
            }

    for tissue_type, tissue_data in tissue_densities.items():
        total_cell_count = tissue_data['total_cell_count']
        total_volume = tissue_data['total_volume']
        average_cell_density = total_cell_count / total_volume
        tissue_densities[tissue_type] = average_cell_density

    return tissue_densities

