Certainly! To add **logout functionality** in your Redux Toolkit slice, you just need to:

1. Add a **logout action (reducer)** in your slice.
2. In the logout reducer, set the userInfo to null, status to idle, and remove "userInfo" from localStorage.

**Here's the updated code:**

```js
/* eslint-disable no-unused-vars */
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import axios from '../api/api';

const USERS_URL = '/auth/email';

export const login = createAsyncThunk('user/login', async (data) => {
  const response = await axios.post(`${USERS_URL}/login`, data);
  return response.data;
});

export const register = createAsyncThunk('user/register', async (data) => {
  const response = await axios.post(`${USERS_URL}/register`, data);
  return response.data;
});

export const updateUser = createAsyncThunk('user/update', async (data) => {
  const response = await axios.put('auth/me', data);
  return response.data;
});

const initialState = {
  userInfo: localStorage.getItem('userInfo')
    ? JSON.parse(localStorage.getItem('userInfo'))
    : null,
  status: 'idle',
  error: null,
};

const userSlice = createSlice({
  name: 'user',
  initialState,
  reducers: {
    // Add a logout reducer here
    logout: (state) => {
      state.userInfo = null;
      state.status = 'idle';
      state.error = null;
      localStorage.removeItem('userInfo');
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(login.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(login.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.userInfo = action.payload;
        localStorage.setItem('userInfo', JSON.stringify(action.payload));
      })
      .addCase(login.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message;
      })
      .addCase(register.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(register.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.userInfo = action.payload;
        localStorage.setItem('userInfo', JSON.stringify(action.payload));
      })
      .addCase(register.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message;
      })
      .addCase(updateUser.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(updateUser.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.userInfo = action.payload;
        localStorage.setItem('userInfo', JSON.stringify(action.payload));
      })
      .addCase(updateUser.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message;
      })
      .addDefaultCase((state) => {});
  },
});

export const { logout } = userSlice.actions;

export default userSlice.reducer;
```

