def count_common_hashtags(posts1, posts2):
    # Create sets to store unique hashtags from both lists
    hashtags1 = set()
    hashtags2 = set()

    # Extract hashtags from posts1
    for post in posts1:
        words = post.split()
        for word in words:
            if word.startswith("#"):
                hashtags1.add(word)

    # Extract hashtags from posts2
    for post in posts2:
