def is_prime(n):
    if n <= 1 or (n % 2 == 0 and n > 2): 
        return False
    return all(n % i for i in range(3, int(n**0.5) + 1, 2))

def transpose(seq):
    result = []
    for num in seq:
        root = num ** 0.5
        if root.is_integer() and is_prime(root):
            result.append(root)
        else:
            result.append(num ** (1/3.0))
    return result

