def remove_comments(s):
    stack = []
    result = []
    i = 0
    while i < len(s):
        if s[i] == '[':
            stack.append('[')
            i += 1
            while stack and i < len(s):
                if s[i] == '[':
                    stack.append('[')
                elif s[i] == ']':
                    stack.pop()
                i += 1
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)

