Пример функции по вашему описанию (в стиле вашей второй функции):

```actionscript
private function startPressed(e:MouseEvent = null):void
{
    // Закрываем старую GUI
    while (this.guiLayer.numChildren > 0)
    {
        this.guiLayer.removeChildAt(0);
    }

    // Настройки нового окна
    var options:NativeWindowInitOptions = new NativeWindowInitOptions();
    options.renderMode = "direct";
    options.maximizable = true;
    var window:NativeWindow = new NativeWindow(options);

    window.minSize = new Point(1024, 768);
    window.maxSize = new Point(4095, 2880);
    window.stage.scaleMode = StageScaleMode.NO_SCALE;
    window.stage.align = StageAlign.TOP_LEFT;

    // flashvars, если нужно прокинуть параметры
    var flashvars:URLVariables = new URLVariables();
    flashvars["locale"] = "ru";
    flashvars["rnd"] = Math.random();

    // Составляем URL с параметрами (GET)
    var url:String = "battles.swf?" + flashvars.toString();

    // Лоадер
    var loader:Loader = new Loader();
    var context:LoaderContext = new LoaderContext(false, ApplicationDomain.currentDomain);

    loader.contentLoaderInfo.addEventListener(Event.COMPLETE, onSWFLoaded);
    loader.contentLoaderInfo.addEventListener(IOErrorEvent.IO_ERROR, onLoaderError);
    loader.load(new URLRequest(url), context);

    window.stage.addChild(loader);
    window.activate();
    window.addEventListener(Event.CLOSE, onWindowClose);
