    let steps = Math.max(
        Math.abs(x2 - x1),
        Math.abs(y2 - y1),
        Math.abs(z2 - z1)
    );
    for (let i = 0; i <= steps; i++) {
        let t = steps === 0 ? 0 : i / steps;
        let x = Math.round(x1 + (x2 - x1) * t);
        let y = Math.round(y1 + (y2 - y1) * t);
        let z = Math.round(z1 + (z2 - z1) * t);
        // Make a disk or small sphere around the path
        for (let dx = -radius; dx <= radius; dx++) {
            for (let dy = -radius; dy <= radius; dy++) {
                for (let dz = -radius; dz <= radius; dz++) {
                    if (dx * dx + dy * dy + dz * dz <= radius * radius) {
                        world.setBlock(x + dx, y + dy, z + dz, id);
                    }
                }
            }
        }
    }
}
```

---

### Option 2: Path through a list of points

```js
// points: array of [x, y, z] coordinates
function pathBlock(points, radius, id) {
    for (let i = 1; i < points.length; i++) {
        let [x1, y1, z1] = points[i - 1];
        let [x2, y2, z2] = points[i];
        pathBlockSegment(x1, y1, z1, x2, y2, z2, radius, id);
    }
}

