    if m == 0:
        return n
    else:
        return gcd(m, n % m)

def solve(n, m):
    if is_mersenne_prime(n) and is_mersenne_prime(m):
        return gcd(n, m)

print(f'The GCD of the given Mersenne prime numbers is: {solve(n, m)}')
